from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5
_FIELDS = ("x", "y", "value", "quality")


def _err(message: str) -> dict:
    return {"ok": False, "error": message}


def _int_field(obs: dict, name: str):
    value = obs.get(name)
    if not isinstance(value, int):
        return None
    return value


def _cell_index(value: int, cell_size: int, extent: int, tolerance: int):
    """Map a coordinate to a column/row, or None when it must be dropped.

    Coordinates below zero or beyond the tolerance window are dropped; values
    within one cell of the far edge clamp onto the last column/row.
    """
    if value < 0:
        return None
    index = value // cell_size
    if index < extent:
        return index
    if value - extent * cell_size < tolerance:
        return extent - 1
    return None


def _validate_grid(raw: dict, key: str, message: str) -> tuple:
    value = raw.get(key)
    if not isinstance(value, dict):
        return None, message
    if "width" not in value or "height" not in value or "cell_size" not in value:
        return None, message
    return value, message


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return _err("malformed input")
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return _err("missing field")

    grid, message = _validate_grid(raw, "grid", "bad grid")
    if grid is None:
        return _err(message)

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return _err("bad width")
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return _err("bad height")
    if not isinstance(cell_size, int) or cell_size < 1:
        return _err("bad cell size")
    fill_value = raw["fill_value"]
    if not isinstance(fill_value, int):
        return _err("bad fill value")
    observations = raw["observations"]
    if not isinstance(observations, list):
        return _err("bad observations")

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict):
            return _err("bad observation")
        x = _int_field(obs, "x")
        y = _int_field(obs, "y")
        value = _int_field(obs, "value")
        quality = _int_field(obs, "quality")
        if x is None or y is None or value is None or quality is None:
            return _err("bad observation")
        if quality < 0 or quality > 100:
            return _err("bad observation")

        if quality < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col = _cell_index(x, cell_size, width, tolerance)
        row = _cell_index(y, cell_size, height, tolerance)
        if col is None or row is None:
            dropped = dropped + 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + value
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded[key] = True

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
