    k = r.random()
    if k < 0.05:
        return {"grid": {"width": 2, "height": 2, "cell_size": 3}, "obs": []}
    if k < 0.08:
        return [1, 2, 3]
    if k < 0.10:
        return None
    if k < 0.12:
        return 3.14
    raw = {
        "grid": {"width": r.randint(1, 6), "height": r.randint(1, 6), "cell_size": r.randint(1, 5)},
        "fill_value": r.randint(-50, 50),
        "observations": [],
    }
    n = r.randint(0, 12)
    for _ in range(n):
        # mutate randomness: sometimes drop keys, bad types
        kind = r.random()
        if kind < 0.04:
