import importlib.util, random
def load(p):
    s=importlib.util.spec_from_file_location(p,p); m=importlib.util.module_from_spec(s); s.loader.exec_module(m); return m
o=load('/tmp/orig_accum.py'); n=load('accumulate_grid.py')
random.seed(99)
def mk(r):
    if r.random()<0.08: return None if r.random()<.5 else [1,2]
    raw={'grid':{'width':r.randint(1,6),'height':r.randint(1,6),'cell_size':r.randint(1,5)},'fill_value':r.randint(-50,50),'observations':[]}
    if r.random()<0.04: raw['observations']='x'
    for _ in range(r.randint(0,12)):
        o={'x':r.randint(-8,20),'y':r.randint(-8,20),'value':r.randint(-100,100),'quality':r.randint(0,100)}
        k=r.random()
        if k<0.06: o['quality']=r.randint(-5,105)
        elif k<0.10: o['x']='bad'
        elif k<0.13: o.pop('value',None)
        elif k<0.16: o['quality']=3.5
        if isinstance(raw['observations'],list): raw['observations'].append(o)
    return raw
mm=0
for i in range(30000):
    inp=mk(random)
    try: a=o.accumulate_grid(inp); ea='ok'
    except Exception as e: a=None; ea='r'+type(e).__name__
    try: b=n.accumulate_grid(inp); eb='ok'
    except Exception as e: b=None; eb='r'+type(e).__name__
    if ea!=eb or a!=b:
        mm+=1; print('DIFF',repr(inp)); print(' orig',ea,a); print(' new ',eb,b)
        if mm>5: break
print('done, mismatches:',mm)
